mapper.sql:
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{startDate} AND #{endDate}
            AND TRUNC(c.VISIT_DATE) != TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS appointmentRegister,
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND TRUNC(c.VISIT_DATE) != TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS appointmentRegisterLast,
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{startDate} AND #{endDate}
            AND TRUNC(c.VISIT_DATE) = TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS todayRegister,
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND TRUNC(c.VISIT_DATE) = TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS todayRegisterLast,
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{startDate} AND #{endDate}
            AND TRUNC(c.VISIT_DATE) != TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS appointmentFetch,
COUNT(CASE WHEN c.STAT_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND TRUNC(c.VISIT_DATE) != TRUNC(c.REGISTERING_DATE) AND c.IS_RETURN_TYPE != -1 THEN 1 END) AS appointmentFetchLast,
COUNT(CASE WHEN c.RETURNED_DATE BETWEEN #{startDate} AND #{endDate}
            AND c.IS_RETURN_TYPE = -1 AND c.REGISTRATION_STATUS != 0 THEN 1 END) AS refund,
COUNT(CASE WHEN c.RETURNED_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND c.IS_RETURN_TYPE = -1 AND c.REGISTRATION_STATUS != 0 THEN 1 END) AS refundLast

c.APPOINTS_INDICATOR = 2
AND (c.STAT_DATE BETWEEN #{lastStartDate} AND #{endDate}
     OR c.RETURNED_DATE BETWEEN #{lastStartDate} AND #{endDate})

COUNT(CASE WHEN r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
            AND NVL(r.TOTAL_CHARGES, 0) >= 0 THEN 1 END) AS outpatientCharge,
COUNT(CASE WHEN r.STAT_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND NVL(r.TOTAL_CHARGES, 0) >= 0 THEN 1 END) AS outpatientChargeLast,
COUNT(CASE WHEN r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
            AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0 THEN 1 END) AS outpatientRefund,
COUNT(CASE WHEN r.STAT_DATE BETWEEN #{lastStartDate} AND #{lastEndDate}
            AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0 THEN 1 END) AS outpatientRefundLast

mapper.select:
SELECT

FROM TR_OUTP_FIN_RCPT_ACCT r
WHERE r.STAT_DATE BETWEEN #{lastStartDate} AND #{endDate}

SELECT

FROM TR_OUTP_FIN_RCPT_ACCT r
WHERE r.STAT_DATE BETWEEN #{lastStartDate} AND #{endDate}
  AND r.OPERATOR_NO = #{cashier}

SELECT

FROM tr_inpat_prepay_rcpt p
WHERE p.stat_date BETWEEN #{lastStartDate} AND #{endDate}

SELECT

FROM tr_inpat_prepay_rcpt p
WHERE p.stat_date BETWEEN #{lastStartDate} AND #{endDate}
  AND p.operator_no = #{cashier}

SELECT

FROM tr_disch_settle_visit v
WHERE v.stat_date BETWEEN #{lastStartDate} AND #{endDate}

SELECT
COUNT(CASE WHEN m.stat_date BETWEEN #{startDate} AND #{endDate} THEN 1 END) AS dischargeSettlement,
COUNT(CASE WHEN m.stat_date BETWEEN #{lastStartDate} AND #{lastEndDate} THEN 1 END) AS dischargeSettlementLast
FROM tr_settle_master m
WHERE m.stat_date BETWEEN #{lastStartDate} AND #{endDate}
  AND m.operator_no = #{cashier}

SELECT period AS "period", dim AS "dim", SUM(net_cnt) AS "net_cnt", SUM(all_cnt) AS "all_cnt", SUM(tuihao) AS "tuihao", SUM(yy_ok) AS "yy_ok", SUM(yy_cancel) AS "yy_cancel", SUM(jf) AS "jf", SUM(tf) AS "tf" FROM ( SELECT TRUNC(c.STAT_DATE, 'MM')TRUNC(c.STAT_DATE) AS period, c.OPERATOR_NO AS dim, SUM(CASE WHEN c.IS_RETURN_TYPE = 1 THEN 1 ELSE 0 END) AS net_cnt, COUNT(1) AS all_cnt, 0 AS tuihao, 0 AS yy_ok, 0 AS yy_cancel, 0 AS jf, 0 AS tf FROM TR_OUTP_FIN_CLINIC_MASTER c WHERE c.STAT_DATE BETWEEN #{startDate} AND #{endDate} AND c.APPOINTS_INDICATOR = 2
AND c.OPERATOR_NO = #{dimValue}
GROUP BY TRUNC(c.STAT_DATE, 'MM')TRUNC(c.STAT_DATE), c.OPERATOR_NO UNION ALL SELECT TRUNC(c.RETURNED_DATE, 'MM')TRUNC(c.RETURNED_DATE) AS period, c.OPERATOR_NO AS dim, 0 AS net_cnt, 0 AS all_cnt, COUNT(1) AS tuihao, 0 AS yy_ok, 0 AS yy_cancel, 0 AS jf, 0 AS tf FROM TR_OUTP_FIN_CLINIC_MASTER c WHERE c.RETURNED_DATE BETWEEN #{startDate} AND #{endDate} AND c.APPOINTS_INDICATOR = 2 AND c.IS_RETURN_TYPE = -1 AND c.REGISTRATION_STATUS <> 0
AND c.OPERATOR_NO = #{dimValue}
GROUP BY TRUNC(c.RETURNED_DATE, 'MM')TRUNC(c.RETURNED_DATE), c.OPERATOR_NO UNION ALL SELECT TRUNC(r.STAT_DATE, 'MM')TRUNC(r.STAT_DATE) AS period, r.OPERATOR_NO AS dim, 0 AS net_cnt, 0 AS all_cnt, 0 AS tuihao, 0 AS yy_ok, 0 AS yy_cancel, SUM(CASE WHEN NVL(r.TOTAL_CHARGES, 0) >= 0 THEN 1 ELSE 0 END) AS jf, SUM(CASE WHEN r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0 THEN 1 ELSE 0 END) AS tf FROM TR_OUTP_FIN_RCPT_ACCT r WHERE r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
AND r.OPERATOR_NO = #{dimValue}
GROUP BY TRUNC(r.STAT_DATE, 'MM')TRUNC(r.STAT_DATE), r.OPERATOR_NO ) GROUP BY period, dim ORDER BY period, dim
